window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-30601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάμφυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra π · nº geral 30601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 misto de todas as tribos ou povos 2 de todas as espécies. 〈πᾶν, φῦλον〉</p></section></article>\n<article id=\"entry-dgp-30602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάμφυλος1, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra π · nº geral 30602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 da Panfília; panfílio ♦ ὁ Πάμ­φυλος 2 habitante da Panfília; panfílio 3 pl. os panfílios, os descendentes de Pânfilo, uma das três tribos dóricas.</p></section></article>\n<article id=\"entry-dgp-30603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάμφυλος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra π · nº geral 30603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pânfilo, um dos heráclidas.</p></section></article>\n<article id=\"entry-dgp-30604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάμψυχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra π · nº geral 30604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">completamente vivo. 〈πᾶν, ψυχή〉</p></section></article>\n<article id=\"entry-dgp-30605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πᾶν</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra π · nº geral 30605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neutro de πᾶς.</p></section></article>\n<article id=\"entry-dgp-30606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάν, Πανός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra π · nº geral 30606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pã, deus dos campos, dos rebanhos. 〈πάομαι〉</p></section></article>\n<article id=\"entry-dgp-30607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάναβρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra π · nº geral 30607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">completamente efeminado. 〈παν, ἁβρός〉</p></section></article>\n<article id=\"entry-dgp-30608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra π · nº geral 30608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente santo; sagrado. 〈πᾶν, ἄγος〉</p></section></article>\n<article id=\"entry-dgp-30609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάναγρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra π · nº geral 30609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que pode suster ou conter toda espécie de presa (rede, viveiro). 〈πᾶν, ἄγρα〉</p></section></article>\n<article id=\"entry-dgp-30610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παναθήναια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra π · nº geral 30610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">as Panatenéias, festas atenienses em honra a Atena; as Grandes Panatenéias eram quadrienais e as Pequenas, anuais ou trienais. 〈πᾶν, Ἀθηναῖος〉</p></section></article>\n<article id=\"entry-dgp-30611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παναθηναικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra π · nº geral 30611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 das Panatenéias ♦ ὁ Παναθηναικός [λόγος] 2 discurso sobre as Panatenéias, obra de Isó­crates. 〈Παναθήναια〉</p></section></article>\n<article id=\"entry-dgp-30612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάθλιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra π · nº geral 30612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente infeliz; tomado pelo infortúnio. 〈πᾶν, ἄθλιος〉</p></section></article>\n<article id=\"entry-dgp-30613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάναιθος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra π · nº geral 30613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">todo resplandecente. 〈πᾶν, αἴθω〉</p></section></article>\n<article id=\"entry-dgp-30614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναίολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra π · nº geral 30614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 variadamente cinzelado ou bordado 2 muito variado; multiforme 3 de sons variados (lamentação). 〈πᾶν, αἰόλος〉</p></section></article>\n<article id=\"entry-dgp-30615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναίτιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra π · nº geral 30615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é a causa e o princípio de tudo 2 culpado de tudo; único culpado. 〈πᾶν, αἰτία〉</p></section></article>\n<article id=\"entry-dgp-30616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάκεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra π · nº geral 30616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 remédio contra todos os males ♦ Πανάκεια 2 Panacéia, lit. “a que ajuda a todos”, filha de Asclépio. 〈πᾶν, ἄκος〉</p></section></article>\n<article id=\"entry-dgp-30617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναληθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra π · nº geral 30617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">totalmente verdadeiro. 〈πᾶν, ἀληθής〉</p></section></article>\n<article id=\"entry-dgp-30618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναληθῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra π · nº geral 30618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo muito verdadeiro; realmente.</p></section></article>\n<article id=\"entry-dgp-30619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναλκής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra π · nº geral 30619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente forte; todo-poderoso; onipotente.</p></section></article>\n<article id=\"entry-dgp-30620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάλωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra π · nº geral 30620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sujeita tudo. 〈πᾶν, ἁλωτός〉</p></section></article>\n<article id=\"entry-dgp-30621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάμερος</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra π · nº geral 30621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = πανήμερος.</p></section></article>\n<article id=\"entry-dgp-30622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάπαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra π · nº geral 30622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito tenro; delicadíssimo. 〈πᾶν, ἁπαλός〉</p></section></article>\n<article id=\"entry-dgp-30623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάποτμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra π · nº geral 30623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente desafortunado; desventurado; infelicíssimo. 〈πᾶν, ἄποτμος〉</p></section></article>\n<article id=\"entry-dgp-30624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάργυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra π · nº geral 30624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">todo de prata; de prata pura. 〈πᾶν, ἄργυρος〉</p></section></article>\n<article id=\"entry-dgp-30625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάρετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra π · nº geral 30625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem todas as virtudes; inteiramente virtuoso; excelente; perfeito. 〈πᾶν, ἀρετή〉</p></section></article>\n<article id=\"entry-dgp-30626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανάρκετος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra π · nº geral 30626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é suficiente para tudo, i.e., grande; forte; poderoso. 〈πᾶν, ἀρκέω〉</p></section></article>\n<article id=\"entry-dgp-30627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναρμόνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra π · nº geral 30627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cujas partes todas estão ajustadas; disposto com acordo perfeito; harmonioso. 〈πᾶν, ἁρμονία〉</p></section></article>\n<article id=\"entry-dgp-30628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάναρχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra π · nº geral 30628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que comanda todos; potentíssimo. 〈πᾶν, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-30629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναφῆλιξ, ικος</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra π · nº geral 30629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que não tem mais nenhum companheiro da sua idade. 〈πᾶν, ἀφῆλιξ〉</p></section></article>\n<article id=\"entry-dgp-30630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παναχαιοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra π · nº geral 30630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">todos os aqueus reunidos, i.e., todos os gregos. 〈πᾶν, Ἀχαιοί〉</p></section></article>\n<article id=\"entry-dgp-30631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παναώριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra π · nº geral 30631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destinado a uma morte extremamente prematura 2 prematuro; precoce. 〈πᾶν, ἀώριος〉</p></section></article>\n<article id=\"entry-dgp-30632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδαισία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra π · nº geral 30632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. -ίη, ης (ἡ) refeição completa em que tudo é farto; refeição a que não falta ninguém. 〈πᾶν, δαίς〉</p></section></article>\n<article id=\"entry-dgp-30633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδακέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra π · nº geral 30633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) extremamente mordaz. 〈πᾶν, δάκνω〉</p></section></article>\n<article id=\"entry-dgp-30634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδάκρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra π · nº geral 30634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chorado por todos; inteiramente deplorável; infelicíssimo 2 que suscita o pranto; acompanhado de lágrimas. 〈πᾶν, δακρύω〉</p></section></article>\n<article id=\"entry-dgp-30635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδαμάτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra π · nº geral 30635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que doma tudo; que sujeita tudo. 〈πᾶν, δαμάω〉</p></section></article>\n<article id=\"entry-dgp-30636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδαμεί</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra π · nº geral 30636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = πανδημεί.</p></section></article>\n<article id=\"entry-dgp-30637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδαμί</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra π · nº geral 30637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = πανδημεί.</p></section></article>\n<article id=\"entry-dgp-30638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδαμος</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra π · nº geral 30638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = πάνδημος.</p></section></article>\n<article id=\"entry-dgp-30639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδεινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra π · nº geral 30639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito temível; terrível; intolerável.</p></section></article>\n<article id=\"entry-dgp-30640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδημεί</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra π · nº geral 30640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com todo o povo, i.e., em massa; em grande número.</p></section></article>\n<article id=\"entry-dgp-30641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδημί</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra π · nº geral 30641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πανδημεί.</p></section></article>\n<article id=\"entry-dgp-30642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδημία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra π · nº geral 30642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 todo o povo ♦ πανδημίᾳ adv. 2 = πανδημεί. 〈πάνδημος〉</p></section></article>\n<article id=\"entry-dgp-30643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδήμιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra π · nº geral 30643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de todo o povo; comum a todo o povo; público 2 que se estende a todo o povo. 〈πᾶν, δῆμος〉</p></section></article>\n<article id=\"entry-dgp-30644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra π · nº geral 30644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de todo o povo; comum a todo o povo; público 2 difundido a todo o povo; geral 3 comum; vulgar; usual. 〈πᾶν, δῆμος〉</p></section></article>\n<article id=\"entry-dgp-30645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδικος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra π · nº geral 30645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente justo. 〈πᾶν, δίκη〉</p></section></article>\n<article id=\"entry-dgp-30646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδίκως</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra π · nº geral 30646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com toda justiça 2 seguramente; exatamente; com certeza.</p></section></article>\n<article id=\"entry-dgp-30647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανδίων, ονος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra π · nº geral 30647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pandíon, rei de Atenas, pai de Erecteu, de Procne e de Filomela.</p></section></article>\n<article id=\"entry-dgp-30648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοκεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra π · nº geral 30648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">albergue; estalagem. 〈πάνδοκος〉</p></section></article>\n<article id=\"entry-dgp-30649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοκεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra π · nº geral 30649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estalajadeiro. 〈πᾶν, δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-30650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοκεύτρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra π · nº geral 30650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estalajadeira. 〈πανδοκεύω〉</p></section></article>\n<article id=\"entry-dgp-30651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοκεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra π · nº geral 30651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hospedar ou albergar todo mundo; acolher. 〈πάνδοκος〉</p></section></article>\n<article id=\"entry-dgp-30652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra π · nº geral 30652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tomar inteiramente para si; encarregar-se totalmente de, gen. 〈πάνδοκος〉</p></section></article>\n<article id=\"entry-dgp-30653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδοκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra π · nº geral 30653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que acolhe a todo mundo; hospitaleiro. 〈πᾶν, δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-30654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανδοχεῖον, πανδοχεύς</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra π · nº geral 30654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = πανδοκεῖον, πανδοκεύς.</p></section></article>\n<article id=\"entry-dgp-30655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνδυρτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra π · nº geral 30655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inteiramente lamentável 2 que se lamenta muito; lamentoso.</p></section></article>\n<article id=\"entry-dgp-30656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανδώρα, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra π · nº geral 30656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. -η, ης (ἡ) Pandora, a primeira mulher. 〈πᾶν, δῶρον〉</p></section></article>\n<article id=\"entry-dgp-30657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανέλληνες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra π · nº geral 30657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">todos os gregos reunidos. 〈πᾶν, Ἕλλην〉</p></section></article>\n<article id=\"entry-dgp-30658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάνεμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra π · nº geral 30658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Πάνημος.</p></section></article>\n<article id=\"entry-dgp-30659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανεργέτας, α</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra π · nº geral 30659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. que realiza tudo. 〈πᾶν, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-30660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανέρημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra π · nº geral 30660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente deserto. 〈πᾶν, ἔρημος〉</p></section></article>\n<article id=\"entry-dgp-30661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανέστιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra π · nº geral 30661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com toda a família. 〈πᾶν, ἑστία〉</p></section></article>\n<article id=\"entry-dgp-30662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανευδαίμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra π · nº geral 30662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος completamente feliz. 〈πᾶν, εὐδαίμων〉</p></section></article>\n<article id=\"entry-dgp-30663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανευμαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra π · nº geral 30663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muito bom temperamento. 〈πᾶν, εὐμαρής〉</p></section></article>\n<article id=\"entry-dgp-30664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυριάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra π · nº geral 30664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">presidente de uma assembléia geral. 〈πανήγυρις, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-30665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra π · nº geral 30665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 celebrar, em assembléia geral, uma festa nacional, com gen. da festa: π. ’Ολύμπια καὶ Κάρνεια plut. celebrar os jogos Olímpicos e os jogos Carneios 2 divertir-se; alegrar-se; estar em festa 3 frequentar feiras, mercados 4 proferir um panegírico em uma festa nacional. 〈πανήγυρις〉</p></section></article>\n<article id=\"entry-dgp-30666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra π · nº geral 30666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de festa nacional (assembléia geral) 2 festivo; solene 3 pretensioso; vaidoso 4 pomposo (estilo) ♦ ὁ πανηγυρικός 5 discurso em uma festa nacional; panegírico celebrativo, encomiástico. 〈πανήγυρις〉</p></section></article>\n<article id=\"entry-dgp-30667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυρικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra π · nº geral 30667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com pompa ou ostentação.</p></section></article>\n<article id=\"entry-dgp-30668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανήγυρις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra π · nº geral 30668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assembléia de todo o povo, reunido para uma festa nacional; reunião festiva 2 reunião para um sacrifício 3 reunião com grande número de participantes 4 festa 5 divertimento; diversão; festa (para os olhos). 〈πᾶν, ἀγορά〉</p></section></article>\n<article id=\"entry-dgp-30669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγύρις</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra π · nº geral 30669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. jôn. contr. de πανήγυρις.</p></section></article>\n<article id=\"entry-dgp-30670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυρισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra π · nº geral 30670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 celebração de festa solene. 2 pompa; ostentação. 〈πανηγυρίζω〉</p></section></article>\n<article id=\"entry-dgp-30671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανηγυριστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra π · nº geral 30671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que comparece a uma festa solene. 〈πανηγυρίζω〉</p></section></article>\n<article id=\"entry-dgp-30672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανῆμαρ</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra π · nº geral 30672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. durante o dia todo. 〈πᾶν, ἦμαρ〉</p></section></article>\n<article id=\"entry-dgp-30673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανημέριος, α, ον,</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra π · nº geral 30673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. παναμέριος 1 que dura o dia inteiro; que leva todo o dia: ναῦς πανημερίη hom. barco que navega o dia todo, παναμέριος ὅδε χρόνος eur. a duração deste dia 2 de todos os dias; de cada dia ♦ πανημέριον adv. 3 durante o dia todo. 〈πᾶν, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-30674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανήμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra π · nº geral 30674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura o dia todo 2 de cada dia; dia a dia ♦ πανήμερον adv. 3 durante toda a jornada. 〈πᾶν, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-30675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάνημος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra π · nº geral 30675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Panemo, nome de um mês do calendário de Argos.</p></section></article>\n<article id=\"entry-dgp-30676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνθηρ, ηρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra π · nº geral 30676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guepardo, felino. 〈πᾶν, θήρ〉</p></section></article>\n<article id=\"entry-dgp-30677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανθοίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra π · nº geral 30677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Pântoo (Polidamante, Eu­forbo, Hiperenor).</p></section></article>\n<article id=\"entry-dgp-30678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανθοινία, α (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra π · nº geral 30678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">refeição farta; banquete. 〈πάνθοινος〉</p></section></article>\n<article id=\"entry-dgp-30679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνθοινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra π · nº geral 30679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">farto; abundante (banquete). 〈πᾶς, θοίνη〉</p></section></article>\n<article id=\"entry-dgp-30680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανθυμαδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra π · nº geral 30680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em completa fúria; com furor. 〈πᾶν, θυμός, -δον〉</p></section></article>\n<article id=\"entry-dgp-30681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνθυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra π · nº geral 30681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se celebra com sacrifícios de todo tipo; augusto; excelso. 〈πᾶν, θύω〉</p></section></article>\n<article id=\"entry-dgp-30682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra π · nº geral 30682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Pã: τάραχος Π. plut. terror pânico, porque os ruídos escutados nas montanhas e nos vales eram atribuídos a Pã. 〈Πάν〉</p></section></article>\n<article id=\"entry-dgp-30683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανίμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra π · nº geral 30683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é todo desejo, i.e., que está cheio de amor 2 inteiramente agradável. 〈πᾶν, ἵμερος〉</p></section></article>\n<article id=\"entry-dgp-30684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra π · nº geral 30684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">terror pânico. 〈Πάν〉</p></section></article>\n<article id=\"entry-dgp-30685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανιώνια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra π · nº geral 30685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festa celebrada por todos os jônios reunidos. 〈πᾶν, Ἵωνες〉</p></section></article>\n<article id=\"entry-dgp-30686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πανιώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra π · nº geral 30686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Paniônio, bosque sagrado próximo de Micale, onde se reuniam todos os jônios para a festa nacional de Posidão. 〈πᾶν, Ἵωνες〉</p></section></article>\n<article id=\"entry-dgp-30687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανλώβητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra π · nº geral 30687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">totalmente desfigurado; horrível.</p></section></article>\n<article id=\"entry-dgp-30688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάννυχα</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra π · nº geral 30688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. cf. πάννυχος.</p></section></article>\n<article id=\"entry-dgp-30689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παννυχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra π · nº geral 30689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 velar a noite toda 2 (chama) arder a noite toda 3 celebrar uma festa à noite. 〈παννυχίς〉</p></section></article>\n<article id=\"entry-dgp-30690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παννύχιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra π · nº geral 30690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura a noite toda; noturno: εὖδον παννύχιοι hom. dormiram toda a noite ♦ παννύχιον adv. 2 durante toda a noite. 〈πᾶν, νύξ〉</p></section></article>\n<article id=\"entry-dgp-30691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παννυχίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra π · nº geral 30691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 festa noturna; vigília religiosa; vigília 2 duração de uma noite. 〈πᾶν, νύξ〉</p></section></article>\n<article id=\"entry-dgp-30692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάννυχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra π · nº geral 30692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura toda a noite; que faz algo durante toda a noite ♦ πάννυχα adv. 2 durante toda a noite. 〈πᾶν, νύξ〉</p></section></article>\n<article id=\"entry-dgp-30693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνοιζυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra π · nº geral 30693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. υος totalmente desgraçado. 〈πᾶν, ὀιζύς〉</p></section></article>\n<article id=\"entry-dgp-30694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανοικεί</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra π · nº geral 30694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πανοικί adv. = πανοικησίᾳ. 〈πᾶν, οἶκος〉</p></section></article>\n<article id=\"entry-dgp-30695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανοικησίᾳ</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra π · nº geral 30695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com toda a casa ou toda a família.</p></section></article>\n<article id=\"entry-dgp-30696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανοικία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra π · nº geral 30696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. -ίη, ης (ἡ) a casa toda; toda a família.</p></section></article>\n<article id=\"entry-dgp-30697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανοίμοι</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra π · nº geral 30697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interj. ai!, ai de mim! 〈πᾶν, οἴμοι〉</p></section></article>\n<article id=\"entry-dgp-30698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνολβος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra π · nº geral 30698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteiramente feliz.</p></section></article>\n<article id=\"entry-dgp-30699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανομιλεί</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra π · nº geral 30699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em tropa compacta; em massa. 〈πᾶν, ὅμιλος〉</p></section></article>\n<article id=\"entry-dgp-30700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανομφαῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra π · nº geral 30700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fonte de todos os oráculos, de todos os presságios (Zeus). 〈πᾶν, ὀμφή〉</p></section></article>\n";
